package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="pricing_slabs") public class PricingSlab{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="rule_id") private PricingRule rule; @Column(name="lower_bound",nullable=false,precision=19,scale=4) private BigDecimal lowerBound; @Column(name="upper_bound",precision=19,scale=4) private BigDecimal upperBound; @Column(name="flat_fee",precision=19,scale=4) private BigDecimal flatFee; @Column(name="percentage_rate",precision=12,scale=6) private BigDecimal percentageRate; @Column(name="sequence_no",nullable=false) private int sequenceNo;
 public UUID getId(){return id;} public PricingRule getRule(){return rule;} public void setRule(PricingRule v){rule=v;} public BigDecimal getLowerBound(){return lowerBound;} public void setLowerBound(BigDecimal v){lowerBound=v;} public BigDecimal getUpperBound(){return upperBound;} public void setUpperBound(BigDecimal v){upperBound=v;} public BigDecimal getFlatFee(){return flatFee;} public void setFlatFee(BigDecimal v){flatFee=v;} public BigDecimal getPercentageRate(){return percentageRate;} public void setPercentageRate(BigDecimal v){percentageRate=v;} public int getSequenceNo(){return sequenceNo;} public void setSequenceNo(int v){sequenceNo=v;}
}
